<script setup lang="ts">import{onMounted,reactive,ref,watch}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import http from'../../api/http';import TablePager from'../../shared/components/TablePager.vue';const tab=ref('ecrs'),rows=ref<any[]>([]),page=ref(1),size=ref(20),total=ref(0),dialog=ref(false),form=reactive<any>({});async function load(){const{data}=await http.get(`/plm/${tab.value}`,{params:{page:page.value,size:size.value}});rows.value=data.data.content;total.value=data.data.totalElements}function create(){Object.assign(form,{ecrNo:`ECR-${Date.now().toString().slice(-8)}`,ecrTitle:'',productCode:'',problemDesc:'',changeReason:'',urgency:'NORMAL',proposal:'',plannedEffectiveDate:''});dialog.value=true}async function save(){await http.post('/plm/ecrs',form);dialog.value=false;ElMessage.success('变更申请已创建');await load()}async function impact(r:any){const{value}=await ElMessageBox.prompt('输入影响对象编码（将记录为物料清单影响）','影响分析',{inputPattern:/.+/});await http.put(`/plm/ecrs/${r.id}/impact-analysis`,[{impactType:'BOM',objectCode:value,riskLevel:'MEDIUM',impactDesc:'工程变更影响'}]);ElMessage.success('影响分析已保存');await load()}async function eco(r:any){await http.post(`/plm/ecrs/${r.id}/create-eco`,{ecoNo:`ECO-${Date.now().toString().slice(-8)}`,ecoTitle:r.ecr_title,changeScope:r.proposal,targetType:'BOM',targetCode:'',newVersion:'V2.0'});ElMessage.success('变更命令已生成');tab.value='ecos'}async function action(r:any){if(tab.value==='ecos')await http.post(`/plm/ecos/${r.id}/submit`);else if(tab.value==='ecns')await http.post(`/plm/ecns/${r.id}/implement`);ElMessage.success('业务动作已执行');await load()}watch(tab,()=>{page.value=1;load()});onMounted(load)</script><template><section class="page"><div class="head"><div><span>工程变更管理</span><h1>工程变更闭环</h1><p>变更申请影响分析、变更命令审批、变更通知实施与主数据新版本。</p></div><el-button v-if="tab==='ecrs'" type="primary" @click="create">新增变更申请</el-button></div><el-card shadow="never"><el-tabs v-model="tab"><el-tab-pane label="变更申请" name="ecrs"/><el-tab-pane label="变更命令" name="ecos"/><el-tab-pane label="变更通知" name="ecns"/></el-tabs><el-table :data="rows" stripe><el-table-column v-for="k in Object.keys(rows[0]||{}).slice(0,8)" :key="k" :label="$zhKey(k)" min-width="130" show-overflow-tooltip><template #default="{row}">{{$zh(row[k])}}</template></el-table-column><el-table-column label="操作" width="190"><template #default="{row}"><el-button v-if="tab==='ecrs'" link @click="impact(row)">影响分析</el-button><el-button v-if="tab==='ecrs'" link type="primary" @click="eco(row)">生成变更命令</el-button><el-button v-if="tab!=='ecrs'" link type="primary" @click="action(row)">{{tab==='ecos'?'提交审批':'实施'}}</el-button></template></el-table-column></el-table><TablePager v-model:page="page" v-model:size="size" :total="total" @change="load"/></el-card><el-dialog v-model="dialog" title="新增变更申请" width="680px"><el-form label-position="top"><el-form-item label="变更申请编号"><el-input v-model="form.ecrNo"/></el-form-item><el-form-item label="标题"><el-input v-model="form.ecrTitle"/></el-form-item><el-form-item label="产品编码"><el-input v-model="form.productCode"/></el-form-item><el-form-item label="问题描述"><el-input v-model="form.problemDesc" type="textarea"/></el-form-item><el-form-item label="变更原因"><el-input v-model="form.changeReason"/></el-form-item><el-form-item label="建议方案"><el-input v-model="form.proposal" type="textarea"/></el-form-item></el-form><template #footer><el-button type="primary" @click="save">保存变更申请</el-button></template></el-dialog></section></template><style scoped>.page{max-width:1480px;margin:auto}.head{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:17px}.head h1{margin:6px 0}.head span{color:#3775d6;font-size:10px}.head p{color:#8291a4;font-size:12px}</style>
